/* A surface needs no wrapper. Add the border class to opt into one pseudo-element. */
.lumenmorph {
  background-color: var(--lumen-bg, #302028b3);
  border-radius: var(--lumen-radius, 0.25rem);
  -webkit-backdrop-filter: blur(var(--lumen-blur, 32px)) saturate(var(--lumen-saturation, 1.6));
  backdrop-filter: blur(var(--lumen-blur, 32px)) saturate(var(--lumen-saturation, 1.6));
}

.lumenmorph-border {
  position: relative;
  border: var(--lumen-border-width, 1.5px) solid var(--lumen-border-color, #ffffff30);
}

.lumenmorph-border::before {
  content: "";
  position: absolute;
  inset: calc(-1 * var(--lumen-border-width, 1.5px));
  border-radius: inherit;
  padding: var(--lumen-border-width, 1.5px);
  pointer-events: none;
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  mask-composite: exclude;
}

.lumenmorph-text,
.glassmorphism-text {
  color: var(--lumen-text-color, #ffffffb3);
}

@supports (background: color-mix(in srgb, red, transparent)) {
  .lumenmorph {
    background-image: radial-gradient(circle var(--lumen-glow-size, 460px) at var(--lumen-x, 50vw) var(--lumen-y, 35vh), color-mix(in srgb, var(--lumen-glow-color, #ffaa71) calc(var(--lumen-glow-opacity, 0.3) * 100%), transparent), transparent);
    background-attachment: var(--lumen-attachment, fixed);
    background-size: var(--lumen-space, 100vw 100vh);
    background-repeat: no-repeat;
  }

  .lumenmorph-border::before {
    background-image: radial-gradient(circle var(--lumen-glow-size, 460px) at var(--lumen-x, 50vw) var(--lumen-y, 35vh), color-mix(in srgb, var(--lumen-border-glow-color, var(--lumen-glow-color, #ffd4a3)) calc(var(--lumen-border-opacity, 0.9) * 100%), transparent), transparent);
    background-attachment: var(--lumen-attachment, fixed);
    background-size: var(--lumen-space, 100vw 100vh);
    background-repeat: no-repeat;
  }

  @supports (background-clip: text) or (-webkit-background-clip: text) {
    .lumenmorph-text,
    .glassmorphism-text {
      background-color: transparent;
      background-image: radial-gradient(circle at bottom center, color-mix(in srgb, var(--lumen-glow-color, #ffaa71) 10%, transparent), transparent 50%), radial-gradient(circle var(--lumen-text-glow-size, var(--lumen-glow-size, 80vmax)) at var(--lumen-x, 50vw) var(--lumen-y, 35vh), color-mix(in srgb, var(--lumen-glow-color, #ffaa71) calc(var(--lumen-text-glow-opacity, 1) * 100%), transparent), transparent);
      background-attachment: scroll, var(--lumen-attachment, fixed);
      background-size: var(--lumen-space, 100vw 100vh);
      background-position: center center, 0 0;
      background-repeat: no-repeat;
      -webkit-background-clip: text;
      background-clip: text;
      -webkit-backdrop-filter: none;
      backdrop-filter: none;
      -webkit-text-stroke: var(--lumen-text-stroke-width, 2px) transparent;
    }
  }
}

@media (prefers-reduced-transparency: reduce) {
  .lumenmorph {
    background: var(--lumen-solid-bg, #302028);
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
}

@media (forced-colors: active) {
  .lumenmorph {
    background: Canvas;
    color: CanvasText;
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
  .lumenmorph-border { border-color: CanvasText; }
  .lumenmorph-border::before { display: none; }
  .lumenmorph-text,
  .glassmorphism-text { background: none; color: CanvasText; -webkit-text-stroke: 0; }
}

.slidebox {
  --_container-width-ratio: var(--slidebox-width, 2);
  --_thumb-spacing-ratio: var(--slidebox-spacing, .33);
  --_deform: var(--slidebox-deform, .1);
  --_duration: var(--slidebox-duration, 200ms);
  --_easing-function: var(--slidebox-easing, ease-in-out);
  --_track: var(--slidebox-track, Field);
  --_border: var(--slidebox-border, ButtonBorder);
  --_off: var(--slidebox-off, FieldText);
  --_on: var(--slidebox-on, var(--_accent, light-dark(#0b75ff, SelectedItem)));
  appearance: none;
  -webkit-appearance: none;
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: calc(1em * var(--_container-width-ratio));
  height: 1em;
  font-size: var(--slidebox-size, 54px);
  padding: 0;
  border: 1px solid var(--_border);
  border-radius: 100vw;
  background: var(--_track);
  cursor: pointer;
}
@supports (color: AccentColor) {
  .slidebox { --_accent: AccentColor; }
}
.slidebox::after {
  --_start: 0; --_end: 1;
  box-sizing: border-box;
  content: "";
  display: block;
  flex: 1 1 auto;
  min-width: 0;
  width: calc((1 - var(--_thumb-spacing-ratio)) * 1em);
  height: calc((1 - var(--_thumb-spacing-ratio)) * 1em);
  margin-block: calc(var(--_thumb-spacing-ratio) * .5em);
  margin-inline-start: calc((1em * var(--_container-width-ratio) - 1em) * var(--_start) + var(--_thumb-spacing-ratio) * .5em);
  margin-inline-end: calc((1em * var(--_container-width-ratio) - 1em) * var(--_end) + var(--_thumb-spacing-ratio) * .5em);
  border-radius: inherit;
  border: 1px solid var(--_track);
  background: var(--_off);
  transition: background var(--_duration) var(--_easing-function), margin-inline-start var(--_duration) var(--_easing-function), margin-inline-end var(--_duration) var(--_easing-function);
  transition-delay: 0s, 0s, calc(var(--_duration) * var(--_deform));
}
.slidebox:checked::after {
  --_start: 1; --_end: 0;
  background: var(--_on);
  transition-delay: 0s, calc(var(--_duration) * var(--_deform)), 0s;
}
.slidebox:not(:checked):active::after { --_end: calc(1 - var(--_deform)); }
.slidebox:checked:active::after { --_start: calc(1 - var(--_deform)); }
.slidebox:disabled { cursor: not-allowed; opacity: .5; }
.slidebox[data-slidebox-dragging]::after {
  margin-inline-start: calc((1em * var(--_container-width-ratio) - 1em) * max(0, var(--slidebox-drag-progress) - max(0, var(--slidebox-drag-stretch, 0))) + var(--_thumb-spacing-ratio) * .5em);
  margin-inline-end: calc((1em * var(--_container-width-ratio) - 1em) * max(0, 1 - var(--slidebox-drag-progress) - max(0, -1 * var(--slidebox-drag-stretch, 0))) + var(--_thumb-spacing-ratio) * .5em);
  transition: none;
}
@media (forced-colors: active) {
  .slidebox { --_track: Field; --_border: ButtonBorder; --_off: FieldText; --_on: Highlight; }
}
@media (prefers-reduced-motion: reduce) {
  .slidebox::after { transition-duration: .01ms; transition-delay: 0ms; }
}

.slidebox-range {
  --_size: var(--slidebox-size, 24px);
  --_spacing: var(--slidebox-spacing, .33);
  --_range-inset: max(0px, calc(var(--_size) * var(--_spacing) * .5));
  --_thumb-size: calc(var(--_size) * (1 - var(--_spacing)));
  --_deform: var(--slidebox-deform, .1);
  --_duration: var(--slidebox-duration, 200ms);
  --_easing: var(--slidebox-easing, ease-in-out);
  --_track: var(--slidebox-track, Field);
  --_border: var(--slidebox-border, ButtonBorder);
  --_on: var(--slidebox-on, var(--_accent, light-dark(#0b75ff, SelectedItem)));
  appearance: none;
  -webkit-appearance: none;
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  height: var(--_size);
  margin: 0;
  padding-block: 0;
  padding-inline: var(--_range-inset);
  border: 1px solid var(--_border);
  border-radius: var(--slidebox-radius, 100vw);
  background: var(--_track);
  color: var(--_on);
  cursor: pointer;
  accent-color: var(--_on);
}
.slidebox-range[data-slidebox-range-fill] {
  --_fill-size: max(0px, min(var(--_thumb-size), calc(var(--_size) - 2px)));
  --_fill-stop: clamp(0px, calc(var(--_thumb-size) * .5 + (100% - var(--_thumb-size)) * clamp(0, var(--slidebox-range-fill, 0), 1)), 100%);
  background-image:
    radial-gradient(circle closest-side, var(--_fill-color, var(--_on)) calc(100% - .5px), transparent 100%),
    linear-gradient(to right, transparent 0 calc(var(--_fill-size) * .5), var(--_fill-color, var(--_on)) calc(var(--_fill-size) * .5) var(--_fill-stop), transparent var(--_fill-stop)),
    var(--_range-track-image, none);
  background-size: var(--_fill-size) var(--_fill-size), max(0px, calc(100% - 2 * var(--_range-inset))) var(--_fill-size), 100vw 100vh;
  background-position: left var(--_range-inset) center, center, 0 0;
  background-repeat: no-repeat;
  background-attachment: scroll, scroll, fixed;
  background-clip: padding-box;
}
.slidebox-range[data-slidebox-range-fill]:dir(rtl) {
  background-image:
    radial-gradient(circle closest-side, var(--_fill-color, var(--_on)) calc(100% - .5px), transparent 100%),
    linear-gradient(to left, transparent 0 calc(var(--_fill-size) * .5), var(--_fill-color, var(--_on)) calc(var(--_fill-size) * .5) var(--_fill-stop), transparent var(--_fill-stop)),
    var(--_range-track-image, none);
  background-position: right var(--_range-inset) center, center, 0 0;
}
.slidebox-range::-webkit-slider-runnable-track {
  box-sizing: border-box;
  height: calc(var(--_size) - 2px);
  border: 0;
  border-radius: var(--slidebox-radius, 100vw);
  background: transparent;
}
.slidebox-range::-moz-range-track {
  box-sizing: border-box;
  height: calc(var(--_size) - 2px);
  border: 0;
  border-radius: var(--slidebox-radius, 100vw);
  background: transparent;
}
.slidebox-range::-webkit-slider-thumb {
  appearance: none;
  -webkit-appearance: none;
  box-sizing: border-box;
  width: calc(var(--_size) * (1 - var(--_spacing)));
  height: calc(var(--_size) * (1 - var(--_spacing)));
  margin-top: calc(var(--_size) * var(--_spacing) / 2 - 1px);
  border: 1px solid var(--_track);
  border-radius: var(--slidebox-radius, 100vw);
  background: var(--_on);
  transition: none;
}
.slidebox-range::-moz-range-thumb {
  box-sizing: border-box;
  width: calc(var(--_size) * (1 - var(--_spacing)));
  height: calc(var(--_size) * (1 - var(--_spacing)));
  border: 1px solid var(--_track);
  border-radius: var(--slidebox-radius, 100vw);
  background: var(--_on);
  transition: none;
}
.slidebox-range:focus-visible { outline: 2px solid var(--_on); outline-offset: 3px; }
.slidebox-range[data-slidebox-range-dragging]::-webkit-slider-thumb { background: transparent; border-color: transparent; transition: none; }
.slidebox-range[data-slidebox-range-dragging]::-moz-range-thumb { background: transparent; border-color: transparent; transition: none; }
.slidebox-range:disabled { cursor: not-allowed; opacity: .5; }
@supports (color: AccentColor) {
  .slidebox-range { --_accent: AccentColor; }
}
@media (forced-colors: active) {
  .slidebox-range { --_track: Field; --_border: ButtonBorder; --_on: Highlight; }
  .slidebox-range::-webkit-slider-thumb { border-color: Highlight; }
  .slidebox-range::-moz-range-thumb { border-color: Highlight; }
}
@media (prefers-reduced-motion: reduce) {
  .slidebox-range { transition-duration: .01ms; }
  .slidebox-range::-webkit-slider-thumb { transition-duration: .01ms; }
  .slidebox-range::-moz-range-thumb { transition-duration: .01ms; }
}
